import html

def generate_post(title, content):
    if not isinstance(title, str) or not isinstance(content, str):
        raise TypeError("Both title and content must be strings")

    try:
        escaped_title = html.escape(title)
        escaped_content = html.escape(content)
        return f"<html><head><title>{escaped_title}</title></head><body>{escaped_content}</body></html>"
    except Exception as e:
        raise RuntimeError(f"Failed to generate HTML: {e}")
